import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"50 - TOTP Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/50-totp-configuration.md","filePath":"developers/design-documentation/50-totp-configuration.md"}'),s={name:"developers/design-documentation/50-totp-configuration.md"};function d(i,e,n,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_50-totp-configuration" tabindex="-1">50 - TOTP Configuration <a class="header-anchor" href="#_50-totp-configuration" aria-label="Permalink to &quot;50 - TOTP Configuration&quot;">​</a></h1><h2 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to &quot;Model&quot;">​</a></h2><p>The local <code>User</code> model (<code>database/user_db.py</code>, <code>__tablename__ = &quot;users&quot;</code>) stores an encrypted <code>totp_secret</code> column plus a master switch and three purpose flags. All four flags are <code>Boolean, default=False, nullable=False</code>, so existing installs are never silently locked out.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>totp_enabled</code></td><td>Master TOTP switch</td></tr><tr><td><code>totp_required_for_login</code></td><td>Require TOTP after password login</td></tr><tr><td><code>totp_required_for_mcp</code></td><td>Require fresh TOTP for sensitive Remote MCP consent</td></tr><tr><td><code>totp_required_for_password_reset</code></td><td>Require TOTP on the reset path</td></tr></tbody></table><p>When the master switch is false, <code>is_totp_required_for()</code> returns false for every purpose. The current implementation has no backup-code model or backup-code verification path.</p><h2 id="secret-lifecycle" tabindex="-1">Secret Lifecycle <a class="header-anchor" href="#secret-lifecycle" aria-label="Permalink to &quot;Secret Lifecycle&quot;">​</a></h2><p>Initial user setup generates a base32 secret and stores Fernet ciphertext. <code>get_totp_secret()</code> is the only supported plaintext accessor and includes legacy fallback behavior. <code>get_totp_uri()</code> creates the authenticator provisioning URI through <code>pyotp</code>; <code>verify_totp()</code> checks submitted codes.</p><p>The Profile page can display the QR code and plaintext secret to the authenticated user for enrollment. That response is sensitive and must never be cached or logged.</p><h2 id="login-flow" tabindex="-1">Login Flow <a class="header-anchor" href="#login-flow" aria-label="Permalink to &quot;Login Flow&quot;">​</a></h2><p>When login TOTP is enabled, a correct password creates a short-lived <code>pending_totp_user</code> and does not establish the authenticated user session. <code>/auth/login/totp</code> validates the six-digit code inside the pending window, promotes the session, records <code>totp_verified_at</code>, and then attempts broker-session resume.</p><p>Bad codes are rate limited through the login limit. One bad code does not immediately clear the pending marker; the five-minute freshness window bounds the flow.</p><h2 id="configuration-api" tabindex="-1">Configuration API <a class="header-anchor" href="#configuration-api" aria-label="Permalink to &quot;Configuration API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method/path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /auth/2fa/status</code></td><td>Read master/purpose flags plus <code>last_totp_verified_at</code></td></tr><tr><td><code>POST /auth/2fa/configure</code></td><td>Atomically set master and purpose flags</td></tr></tbody></table><p>Both routes require a valid application session. Changing TOTP policy requires a valid current TOTP code, including disabling it. Disabling the master switch forces all purpose flags false in the same write.</p><p><code>last_totp_verified_at</code> is read from <code>session[&quot;totp_verified_at&quot;]</code>, not from a database column: it reflects this browser session only, and a successful <code>POST /auth/2fa/configure</code> restamps it.</p><h2 id="password-reset-and-mcp" tabindex="-1">Password Reset And MCP <a class="header-anchor" href="#password-reset-and-mcp" aria-label="Permalink to &quot;Password Reset And MCP&quot;">​</a></h2><p>The password-reset route offers TOTP as one of two mutually exclusive methods and verifies through <code>User.verify_totp()</code>. The <code>password_reset</code> purpose flag works as a gate in the other direction: an account with it set is refused the email-link path at <code>step == &quot;select_email&quot;</code> and pushed to the authenticator.</p><p>Remote MCP authorization requires recent TOTP before granting write scope. <code>blueprints/mcp_oauth._is_fresh_totp()</code> treats <code>session[&quot;totp_verified_at&quot;]</code> as fresh for 60 seconds (<code>_FRESH_TOTP_SECONDS</code>), and only when <code>user.is_totp_required_for(&quot;mcp&quot;)</code> and write scope was requested. A successful consent-page TOTP restamps the marker.</p><h2 id="security-rules" tabindex="-1">Security Rules <a class="header-anchor" href="#security-rules" aria-label="Permalink to &quot;Security Rules&quot;">​</a></h2><ul><li>Never read the ciphertext column directly where plaintext is required; use <code>get_totp_secret()</code>.</li><li>Never log the secret, provisioning URI, QR payload, or submitted code.</li><li>TOTP proves possession of the configured authenticator, not broker authorization.</li><li>Purpose flags are effective only while the master switch is on.</li><li>Do not document backup codes until an actual persisted and verified implementation exists.</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>database/user_db.py</code></td><td>Encrypted secret, flags, URI, verification</td></tr><tr><td><code>blueprints/auth.py</code></td><td>Login, status/config, reset integration</td></tr><tr><td><code>blueprints/mcp_oauth.py</code></td><td>Fresh-TOTP check for OAuth consent</td></tr><tr><td><code>frontend/src/pages/Profile.tsx</code></td><td>Enrollment/policy UI</td></tr><tr><td><code>frontend/src/pages/Login.tsx</code></td><td>Pending-login verification</td></tr></tbody></table>',22)])])}const f=t(s,[["render",d]]);export{p as __pageData,f as default};
